\begin{lemma}[Localized Concentration, \cite{foster2019orthogonal}]\label{lem:local-concen}
For any $f \in \mathcal{F}:=\times_{i=1}^d \mathcal{F}_i$ be a multivalued outcome function, that is almost surely absolutely bounded by a constant. Let $\ell(Z ; f(X)) \in \mathbb{R}$ be a loss function that is $O(1)$-Lipschitz in $f(X)$, with respect to the $\ell_2$ norm. Let $\delta_n=\Omega\left(\sqrt{\frac{d \log \log (n)+\log (1 / \zeta)}{n}}\right)$ be an upper bound on the critical radius of $\operatorname{star}\left(\mathcal{F}_i\right)$ for $i \in[d]$. Then for any fixed $h_0 \in \mathcal{F}$, w.p. $1-\zeta$ :
$$
\forall f \in \mathcal{F}:\left|\left(\mathbb{E}_n-\mathbb{E}\right)\left[\ell(Z ; f(X))-\ell\left(Z ; h_0(X)\right)\right]\right|=O\left(d \delta_n \sum_{i=1}^d\left\|f_i-f_{i, 0}\right\|_{2}+d \delta_n^2\right)
$$
If the loss is linear in $f(X)$, i.e. $\ell\left(Z ; f(X)+f^{\prime}(X)\right)=\ell(Z ; f(X))+\ell\left(Z ; f^{\prime}(X)\right)$ and $\ell(Z ; \alpha f(X))=$ $\alpha \ell(Z ; f(X))$ for any scalar $\alpha$, then it suffices that we take $\delta_n=\Omega\left(\sqrt{\frac{\log (1 / \zeta)}{n}}\right)$ that upper bounds the critical radius of $\operatorname{star}\left(\mathcal{F}_i\right)$ for $i \in[d]$.
\end{lemma}
